const express = require('express');
const { SNSClient, PublishCommand } = require('@aws-sdk/client-sns');
const crypto = require('crypto');
const { UserDirectory } = require('../services/userDirectory');

const app = express();
app.use(express.json());

const sns = new SNSClient({ region: 'us-east-1' });

app.post('/api/auth/sms-alert/send-pin', async (req, res) => {
  // Validate caller identity from authenticated pre-auth session
  if (!req.session || !req.session.pendingAuthUserId) {
    return res.status(401).json({ error: 'No active pre-authentication session found' });
  }

  const authenticatedUserId = req.session.pendingAuthUserId;
  const user = await UserDirectory.findById(authenticatedUserId);

  if (!user || !user.phone) {
    return res.status(404).json({ error: 'User phone record not found' });
  }

  const pinCode = crypto.randomInt(100000, 999999).toString();
  await UserDirectory.storePendingPin(authenticatedUserId, pinCode);

  const command = new PublishCommand({
    PhoneNumber: user.phone,
    Message: `Your login verification PIN is: ${pinCode}. Valid for 5 minutes.`,
    MessageAttributes: {
      'AWS.SNS.SMS.SMSType': {
        DataType: 'String',
        StringValue: 'Transactional'
      }
    }
  });

  try {
    await sns.send(command);
    res.json({ success: true, message: 'Verification PIN sent to registered mobile' });
  } catch (err) {
    res.status(500).json({ error: 'Failed to deliver SMS alert' });
  }
});

app.listen(3004);
